
-- Q1 : What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) as revenue
from customer 
group by gender;

-- Q2 : Which customers used a discount but still spent more than the average purchase amount? 

select *
from customer 
where discount_applied = 'Yes' and  purchase_amount > (select avg(purchase_amount) from customer);

-- Q3. Which are the top 5 products with the highest average review rating?

select item_purchased ,round(avg(review_rating),2)as avg_rating
from customer
group by item_purchased
order by avg_rating desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 

select distinct shipping_type from customer group by shipping_type limit 5;

select round(avg(purchase_amount),2) , shipping_type
from customer
where shipping_type in ('Express','Standard')
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select * from customer limit 5;

select case 
        when subscription_status = 'yes' then 'Subscribed'
        when subscription_status = 'no'  then 'Not Subscribed'
        else 'Unknown'
    end as Subscription_status,
	round(avg(purchase_amount),2) as avg_spending ,
	sum(purchase_amount) as total_spending  
from customer 
group by case 
        when subscription_status = 'yes' then 'Subscribed'
        when subscription_status = 'no'  then 'Not Subscribed'
        else 'Unknown'
    end
order by avg_spending,total_spending;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

select * from customer limit 5;
select item_purchased , round(100.0 *sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2)as discounted_rate
from customer
group by item_purchased
order by discounted_rate desc
limit 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 

select min(previous_purchases) as minimum,
	max(previous_purchases) as maximum
 from customer;
 
select customer_type, COUNT(*) as count
from (
	select
        case 
            when previous_purchases between 1 and 20 then 'New'
            when previous_purchases between 21 and 39 then 'Returning'
            when previous_purchases between 40 and 50 then 'Loyal'
            else 'error'
        end as customer_type
    from customer
) t
group by customer_type;

-- Q8. What are the top 3 most purchased products within each category? 

WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select subscription_status , count(customer_id)
from customer
where previous_purchases >5
group by subscription_status;

-- Q10. What is the revenue contribution of each age group?

# did a mistake while putting the data fixed here
update customer
set age_group = 'Young'
where age_group = 'Young Adult';

select rank() over(order by sum(purchase_amount) desc) as 'rank', age_group,sum(purchase_amount) as total_spending
from customer
group by age_group
order by total_spending desc;
